sub legal_values {
  my ($self, $params) = @_;
  Bugzilla->switch_to_shadow_db();
  defined $params->{field} or ThrowCodeError('param_required', {param => 'field'});
  my $field = Bugzilla::Bug::FIELD_MAP->{$params->{field}} || $params->{field};
  my @global_selects = @{Bugzilla->fields({is_select => 1, is_abnormal => 0})};
  if (grep($_->name eq $field, @global_selects)) { $values = get_legal_field_values($field); }
  return { values => $values ? $values : [] };
}

